module proof(input wire [11:0] a, b, input wire cin,
  output wire [12:0] actual, expected, output wire equal);
  wire [11:0] s;
  wire cout;
  ot_v41_ksadd #(.W(12)) dut (.a(a), .b(b), .cin(cin), .s(s), .cout(cout));
  assign actual = {cout, s};
  assign expected = {1'b0, a} + {1'b0, b} + {{12{1'b0}}, cin};
  assign equal = (actual == expected);
endmodule

